'use strict';
import '../styles/main.scss'; // ✅ Apenas uma vez

document.addEventListener('DOMContentLoaded', () => {
  const days = document.querySelectorAll('.calendar__day');
  days.forEach((day, i) => {
    day.textContent = i + 1;
    day.addEventListener('click', () => {
      day.classList.toggle('calendar__day--active');
    });
  });
});

